/* Standalone program around the official cec17_test_func, for tests/test_cec2017_official.py.
   Usage: driver func_num D npoints < points   (run in a directory that holds input_data/)
   Prints f for each point with 17 significant digits. */
#include <stdio.h>
#include <stdlib.h>
#include "cec17_official_decls.h"  /* generated by scripts/fetch_cec2017_official.sh */

char cec17_dir[1024] = "input_data";

int main(int argc, char **argv) {
    int fn = atoi(argv[1]), D = atoi(argv[2]), m = atoi(argv[3]);
    double *x = (double *)malloc(sizeof(double) * D * m), *f = (double *)malloc(sizeof(double) * m);
    for (int i = 0; i < D * m; i++)
        if (scanf("%lf", &x[i]) != 1) return 1;
    cec17_test_func(x, f, D, m, fn);
    for (int i = 0; i < m; i++) printf("%.17g\n", f[i]);
    return 0;
}
